    DELETE FROM public.loan_overdue_recovery_records WHERE branch_id = v_kola_branch;
    DELETE FROM public.loan_payoff_excess_records WHERE branch_id = v_kola_branch;
    DELETE FROM public.repayments WHERE branch_id = v_kola_branch;
